class Order:
    def __init__(self):
        self.id = None
        self.customer_id = None
        self.total = 0.0
        self.status = 'pending'

class OrderService:
    def calculate_total(self, order):
        for item in order.items:
            order.total += item.price * item.qty
        return order.total

    def validate(self, order):
        return order.total > 0
